// #6a993d78df85add81c766e3c — журнал доступа неизменяем (AC5). Кейс ACL-008.
// Попытки записи безвредны даже при сбое защиты: PATCH ставит reason его же текущее значение,
// DELETE адресован несуществующему id (права на таблицу Postgres проверяет до поиска строк → 403 42501).
import { test, expect } from '../../fixtures';
import { openWithApi, SUPABASE_URL } from '../support/api';

const NO_SUCH_ID = '00000000-0000-0000-0000-000000000000';

test.describe('Журнал доступа — неизменяемость (#6a993d78df85add81c766e3c)', () => {
  test('в UI нет правки/удаления, PATCH/DELETE audit_log → 403 42501, запись не изменилась @desktop #6a993d78df85add81c766e3c', async ({ asUser }) => {
    const page = await asUser('admin');
    const api = await openWithApi(page, '/admin/access-log');
    await expect(page.getByRole('heading', { level: 1, name: 'רישום גישה' })).toBeVisible();
    // Источник: AC5 + описание экрана.
    await expect(page.getByText('הרישום אינו ניתן לעריכה או למחיקה')).toBeVisible();

    const rows = page.locator('main table tbody tr');
    await expect(rows.first()).toBeVisible();
    // Единственная кнопка в строках — «כל הגישות»; нет правки/удаления/меню строки.
    const rowButtons = await rows.getByRole('button').allInnerTexts();
    expect(rowButtons.every((t) => t.trim() === 'כל הגישות'), `кнопки в строках: ${[...new Set(rowButtons)].join(' | ')}`).toBeTruthy();
    await expect(rows.locator('[data-testid="row-menu"]')).toHaveCount(0);

    const me = await api.userId();
    const snapRes = await api.get(`audit_log?actor_id=eq.${me}&order=occurred_at.desc&limit=1`);
    expect(snapRes.status()).toBe(200);
    const [before] = (await snapRes.json()) as Record<string, unknown>[];
    expect(before, 'у admin нет ни одной записи в audit_log').toBeTruthy();

    const patch = await api.patch(`audit_log?id=eq.${before.id}`, { reason: before.reason ?? null });
    expect(patch.status(), 'PATCH audit_log').toBe(403);
    expect((await patch.json()).code).toBe('42501');

    const del = await page.request.delete(`${SUPABASE_URL}/rest/v1/audit_log?id=eq.${NO_SUCH_ID}`, { headers: api.headers });
    expect(del.status(), 'DELETE audit_log').toBe(403);
    expect((await del.json()).code).toBe('42501');

    const after = await api.get(`audit_log?id=eq.${before.id}`);
    expect(after.status()).toBe(200);
    expect(await after.json()).toEqual([before]);
  });
});
